  this.face(p010, p011, p111, p110, ey, col, k); if (!noBottom) this.face(p000, p100, p101, p001, ng(ey), col, k);
  this.face(p001, p101, p111, p011, ez, col, k); this.face(p000, p010, p110, p100, ng(ez), col, k);
