  const ex = vnorm(vsub(q, p)); let up = Math.abs(ex[1]) > 0.97 ? [1, 0, 0] : [0, 1, 0];
  const ez = vnorm(vcross(ex, up)), ey = vcross(ez, ex); return [ex, ey, ez];
