// hull: unit length (x -0.5 stern .. 0.5 bow), unit beam (z ±0.5), y -1 (keel) .. 1 (deck) scaled by the freeboard
function hullGeo(){
  const g = new GB(), S = [0, 0.02, 0.06, 0.12, 0.2, 0.35, 0.5, 0.62, 0.72, 0.8, 0.87, 0.93, 0.97, 1.0];
  const wd = s => s < 0.06 ? 0.86 + 2.3*s : s < 0.72 ? 1 : Math.max(0.02, 1 - Math.pow((s - 0.72)/0.28, 2.1));
  const wm = s => s < 0.1 ? 0.6 + 4*s : s < 0.7 ? 1 : Math.max(0, 1 - Math.pow((s - 0.7)/0.28, 1.5));
  const wb = s => s < 0.15 ? 0.15 + 5.5*s : s < 0.66 ? 0.96 : Math.max(0, 0.96*(1 - (s - 0.66)/0.27));
  const prof = s => [[-1, wb(s)*0.6], [-0.85, wb(s)], [-0.02, wm(s)], [0.15, Math.min(wd(s), wm(s)*1.02 + 0.02)], [1, wd(s)]];
  const RED = [0.55, 0.16, 0.13], DECK = [0.36, 0.38, 0.36], one = [1, 1, 1];
  for (let i = 0; i < S.length - 1; i++){
    const A = prof(S[i]), B = prof(S[i + 1]), xa = S[i] - 0.5, xb = S[i + 1] - 0.5;
    for (let j = 0; j < A.length - 1; j++){
      const col = A[j + 1][0] <= 0 ? RED : one, k = A[j + 1][0] <= 0 ? 0 : 1;
      for (const sd of [1, -1]){
        const a = [xa, A[j][0], sd*A[j][1]/2], b = [xb, B[j][0], sd*B[j][1]/2], c = [xb, B[j + 1][0], sd*B[j + 1][1]/2], d = [xa, A[j + 1][0], sd*A[j + 1][1]/2];
        let n = vnorm(vcross(vsub(b, a), vsub(d, a))); if (n[2]*sd < 0) n = [-n[0], -n[1], -n[2]];
        if (sd > 0) g.face(a, d, c, b, n, col, k); else g.face(a, b, c, d, n, col, k);
      }
    }
    const da = A[A.length - 1][1]/2, db = B[B.length - 1][1]/2;
    g.face([xa, 1, -da], [xa, 1, da], [xb, 1, db], [xb, 1, -db], [0, 1, 0], DECK, 0);
  }
  const T = prof(0); for (let j = 0; j < T.length - 1; j++) g.face([-0.5, T[j][0], T[j][1]/2], [-0.5, T[j + 1][0], T[j + 1][1]/2], [-0.5, T[j + 1][0], -T[j + 1][1]/2], [-0.5, T[j][0], -T[j][1]/2], [-1, 0, 0], T[j + 1][0] <= 0 ? RED : one, T[j + 1][0] <= 0 ? 0 : 1);
  return g.geo();
}

