    for (const r of D.roads){ if (r[0] > 11) continue; const P = []; for (let i = 2; i + 1 < r.length; i += 2) P.push([r[i], r[i + 1]]); let Ll = 0; for (let i = 1; i < P.length; i++) Ll += Math.hypot(P[i][0] - P[i - 1][0], P[i][1] - P[i - 1][1]);
      if (Ll > 180 && (!idle || rng() < 0.3)) TT.trucks.push({path:P, loop:true, off:2.2, n:Math.max(1, Math.round(Ll/(idle ? 600 : 160)))}); }

    /* ---- high masts, gates ---- */
    for (const m of D.masts){
      const h0 = hP(m[0], m[1]), ht = 36;
      sbox(ti, m[0], m[1], h0 + ht/2, 0, 0.9, ht, 0.9, [0.62, 0.63, 0.64]);
      sbox(ti, m[0], m[1], h0 + ht + 0.6, gr[2], 5.5, 1.2, 2.2, [0.28, 0.29, 0.3], !idle);
      lamp(m[0], m[1], h0 + ht + 0.2, idle ? [0.62, 0.55, 0.42] : [1, 0.95, 0.86], idle ? 11 : 24);
    }
